changeSet.sql:
DROP TABLE IF EXISTS car_network_components;

CREATE TABLE car_network_components AS
SELECT *
FROM pgr_connectedComponents(
'SELECT rid AS id, source, target, cost, reverse_cost
FROM road_network
WHERE highway IN (
''motorway'', ''motorway_link'',
''trunk'', ''trunk_link'',
''primary'', ''primary_link'',
''secondary'', ''secondary_link'',
''tertiary'', ''tertiary_link'',
''residential'', ''living_street'',
''service'', ''unclassified''
)'
);

CREATE INDEX idx_car_network_components_node
ON car_network_components(node);

CREATE INDEX idx_car_network_components_component
ON car_network_components(component);

DROP TABLE IF EXISTS car_main_component_edges;
CREATE TABLE car_main_component_edges AS WITH largest_component AS ( SELECT component FROM car_network_components GROUP BY component ORDER BY COUNT(*) DESC LIMIT 1 ) SELECT rn.id, rn.name, rn.highway, rn.geom, ST_Length(rn.geom::geography) AS cost, rn.rid, rn.source, rn.target, ST_Length(rn.geom::geography) AS reverse_cost, rn.oneway FROM road_network rn JOIN car_network_components c1 ON rn.source = c1.node JOIN car_network_components c2 ON rn.target = c2.node JOIN largest_component lc ON c1.component = lc.component AND c2.component = lc.component WHERE rn.highway IN ( 'motorway', 'motorway_link', 'trunk', 'trunk_link', 'primary', 'primary_link', 'secondary', 'secondary_link', 'tertiary', 'tertiary_link', 'residential', 'living_street', 'service', 'unclassified' );
CREATE INDEX idx_car_main_component_edges_geom ON car_main_component_edges USING GIST (geom);
CREATE INDEX idx_car_main_component_edges_source ON car_main_component_edges(source);
CREATE INDEX idx_car_main_component_edges_target ON car_main_component_edges(target);
CREATE INDEX idx_car_main_component_edges_highway ON car_main_component_edges(highway);
